"use client";

import { useEffect, useRef, useState } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { Canvas } from "@react-three/fiber";
import ScrollingCoin from "./ScrollingCoin";

gsap.registerPlugin(ScrollTrigger);

export default function Video() {
  const containerRef = useRef<HTMLDivElement>(null); // ← THIS is our trigger
  const fgCanvasRef = useRef<HTMLCanvasElement>(null);
  const bgCanvasRef = useRef<HTMLCanvasElement>(null);

  const fgFrameRef = useRef(0);
  const bgFrameRef = useRef(0);
  const scrollProgressRef = useRef(0);

  const [loaded, setLoaded] = useState(false);

  const fgImagesRef = useRef<HTMLImageElement[]>([]);
  const bgImagesRef = useRef<HTMLImageElement[]>([]);

  const FG_FRAMES = 810;
  const BG_FRAMES = 191;
  const START_BG_AT = 130;
  const CANVAS_W = 1080;
  const CANVAS_H = 1920;

  // Load images
  useEffect(() => {
    let loadedCount = 0;
    const total = FG_FRAMES + BG_FRAMES;

    const loadImage = (url: string, arr: HTMLImageElement[]) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.src = url;
      img.onload = img.onerror = () => {
        loadedCount++;
        if (loadedCount >= total) setLoaded(true);
      };
      arr.push(img);
    };

    for (let i = 1; i <= FG_FRAMES; i++) {
      loadImage(
        `https://ik.imagekit.io/m064cyjlx/phone/frame_${String(i).padStart(5, "0")}.png`,
        fgImagesRef.current
      );
    }
    for (let i = 1; i <= BG_FRAMES; i++) {
      loadImage(
        `https://ik.imagekit.io/m064cyjlx/phonebgtickets/frame_${String(i).padStart(5, "0")}.png`,
        bgImagesRef.current
      );
    }
  }, []);

  // GSAP + ScrollTrigger
  useEffect(() => {
    if (!loaded || !containerRef.current) return;

    const fgCanvas = fgCanvasRef.current!;
    const bgCanvas = bgCanvasRef.current!;
    const fgCtx = fgCanvas.getContext("2d")!;
    const bgCtx = bgCanvas.getContext("2d")!;

    fgCanvas.width = bgCanvas.width = CANVAS_W;
    fgCanvas.height = bgCanvas.height = CANVAS_H;

    const render = () => {
      const fgIndex = Math.min(FG_FRAMES - 1, Math.floor(fgFrameRef.current));
      const bgIndex = Math.min(BG_FRAMES - 1, Math.floor(bgFrameRef.current));

      // Draw BG
      const bgImg = bgImagesRef.current[bgIndex];
      if (bgImg?.complete) {
        bgCtx.clearRect(0, 0, CANVAS_W, CANVAS_H);
        bgCtx.drawImage(bgImg, 0, 0, CANVAS_W, CANVAS_H);
      }

      // Draw FG
      const fgImg = fgImagesRef.current[fgIndex];
      if (fgImg?.complete) {
        fgCtx.clearRect(0, 0, CANVAS_W, CANVAS_H);
        fgCtx.drawImage(fgImg, 0, 0, CANVAS_W, CANVAS_H);
      }
    };

    // MAIN FIX: Use containerRef.current as trigger + proper height
    const tl = gsap.timeline({
      scrollTrigger: {
        trigger: containerRef.current,
        start: "top top",
        end: `+=${(FG_FRAMES - 1) * 8}px`, // Make scroll long enough
        scrub: 1,
        pin: true, // This pins the entire section
        anticipatePin: 1,
        onUpdate: (self) => {
          const progress = self.progress;
          scrollProgressRef.current = progress;

          const targetFrame = progress * (FG_FRAMES - 1);
          fgFrameRef.current = targetFrame;

          // Background starts later
          if (targetFrame >= START_BG_AT) {
            const bgProgress = (targetFrame - START_BG_AT) / (FG_FRAMES - START_BG_AT);
            bgFrameRef.current = bgProgress * (BG_FRAMES - 1);
          } else {
            bgFrameRef.current = 0;
          }

          render();
        },
      },
    });

    render();

    return () => {
      ScrollTrigger.getAll().forEach(st => st.kill());
    };
  }, [loaded]);

  return (
    <>
      {/* THIS is the real scroll container */}
      <div ref={containerRef} className="relative w-full bg-black">
        
        {/* Sticky canvas wrapper */}
        <div className="sticky top-0 h-screen flex items-center justify-center overflow-hidden bg-black">
          
          {/* Background canvas */}
          <canvas
            ref={bgCanvasRef}
            className="absolute inset-0 w-full h-full "
          />

          {/* Foreground phone canvas */}
          <canvas
            ref={fgCanvasRef}
            className="relative z-10 max-w-full h-auto max-h-screen"
            style={{ pointerEvents: "none" }}
          />

          {/* 3D Coin */}
          <div className="absolute inset-0 z-20 pointer-events-none">
            <Canvas camera={{ position: [0, 0, 2.5], fov: 50 }}>
              <ambientLight intensity={3} />
              <directionalLight position={[5, 5, 5]} intensity={4} />
              <pointLight position={[0, 1, 3]} intensity={3} />
              <ScrollingCoin progressRef={scrollProgressRef} />
            </Canvas>
          </div>
        </div>

        {/* This creates the scroll height */}
        <div className="h-[500vh]" />
      </div>
    </>
  );
}

