"use client";

import { useRef } from "react";
import { Canvas, useFrame, useLoader } from "@react-three/fiber";
import { OrbitControls, Environment } from "@react-three/drei";
import * as THREE from "three";
import { TextureLoader } from "three";

function GoldenCoin() {
  const meshRef = useRef<THREE.Group>(null!);
  const logo = useLoader(TextureLoader, "/bump.png"); // Your logo/texture

  useFrame((state, delta) => {
    meshRef.current.rotation.y += delta * 0.8;
    meshRef.current.rotation.x += delta * 0.3;
  });

  return (
    <group ref={meshRef}>
      {/* MAIN GOLD BODY */}
      <mesh castShadow receiveShadow>
        <cylinderGeometry args={[1, 1, 0.18, 128]} />
        <meshStandardMaterial
          color="#f9d71c"
          metalness={1}
          roughness={0.12}
          envMapIntensity={5}
        />
      </mesh>

      {/* REED EDGE – classic coin ridges */}
      <mesh rotation={[Math.PI / 2, 0, 0]}>
        <cylinderGeometry args={[1.02, 1.02, 0.2, 160, 1, true]} />
        <meshStandardMaterial
          color="#e6b800"
          metalness={1}
          roughness={0.08}
          normalMap={createReededNormalMap()}
        />
      </mesh>

      {/* FRONT – embossed with your bump.png */}
      <mesh position={[0, 0, 0.091]}>
        <circleGeometry args={[0.98, 128]} />
        <meshStandardMaterial
          map={logo}
          transparent
          alphaTest={0.1}
          metalness={0.95}
          roughness={0.1}
          envMapIntensity={6}
        />
      </mesh>

      {/* BACK – same texture, flipped */}
      <mesh rotation={[0, Math.PI, 0]} position={[0, 0, -0.091]}>
        <circleGeometry args={[0.98, 128]} />
        <meshStandardMaterial
          map={logo}
          transparent
          alphaTest={0.1}
          metalness={0.95}
          roughness={0.1}
          envMapIntensity={6}
        />
      </mesh>

      {/* Teraawatt green glow rim */}
      <mesh rotation={[Math.PI / 2, 0, 0]}>
        <ringGeometry args={[0.95, 1.05, 64]} />
        <meshBasicMaterial
          color="#05DF72"
          opacity={0.7}
          transparent
          blending={THREE.AdditiveBlending}
        />
      </mesh>
    </group>
  );
}

// Procedural reeded edge normal map (real ridges!)
function createReededNormalMap() {
  const size = 512;
  const canvas = document.createElement("canvas");
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext("2d")!;
  ctx.fillStyle = "#8080ff";
  ctx.fillRect(0, 0, size, size);

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.repeat.x = 80;
  return texture;
}

export default function RealisticCoin() {
  return (
    <div className="w-full h-screen bg-black">
      <Canvas
        shadows
        camera={{ position: [0, 0, 5], fov: 45 }}
        gl={{ antialias: true, toneMapping: THREE.ACESFilmicToneMapping }}
      >
        {/* PRO LIGHTING */}
        <ambientLight intensity={0.5} />
        <directionalLight position={[10, 10, 5]} intensity={3} castShadow />
        <pointLight position={[0, 0, 3]} intensity={8} color="#ffd700" />
        <pointLight position={[-5, 5, -5]} intensity={4} color="#05DF72" />

        {/* HDR Environment for insane reflections */}
        <Environment preset="city" />

        <GoldenCoin />

        <OrbitControls
          enablePan={false}
          enableZoom={true}
          minDistance={3}
          maxDistance={10}
          autoRotate
          autoRotateSpeed={0.5}
        />
      </Canvas>
    </div>
  );
}